solutions.naive:
class Solution:
    def minSpeedOnTime(self, dist, hour):
        if hour <= len(dist) - 1:
            return -1
        limit = int(round(hour * 100))
        def can(speed):
            used = 0
            for d in dist[:-1]:
                used += ((d + speed - 1) // speed) * 100
                if used > limit: return False
            return used + dist[-1] * 100 <= limit * speed
        for s in range(1,10000001):
            if can(s): return s
        return -1

