class Solution:
    def minSpeedOnTime(self, dist, hour):
        if hour <= len(dist) - 1: return -1
        def can(speed):
            total=0.0
            for d in dist[:-1]: total += (d + speed - 1) // speed
            return total + dist[-1] / speed <= hour + 1e-12
        lo,hi,ans=1,10000000,-1
        while lo<=hi:
            mid=(lo+hi)//2
            if can(mid): ans=mid; hi=mid-1
            else: lo=mid+1
        return ans

